import { describe, expect, it } from 'vitest';
import { getDb } from '../../src/db/index.js';
import { listings, servers, type NewServerRow } from '../../src/db/schema.js';
import {
  activeListingsForUser,
  countSearchResults,
  createListing,
  createListingsBatch,
  fulfillListing,
  searchListings,
  softDeleteListing,
  updateListing,
} from '../../src/services/listings.js';
import { setupTestDb } from '../helpers/db.js';

setupTestDb();

const serverRow: NewServerRow = {
  id: '200',
  digestMode: 'disabled',
  digestCron: '0 9 * * *',
  digestTimezone: 'UTC',
  enabledGames: '["mtg"]',
  adminChannelId: null,
  digestDmUserId: null,
  lastDigestAt: null,
  removedAt: null,
  createdAt: 1,
  updatedAt: 1,
};

function seedServer(): void {
  getDb().insert(servers).values(serverRow).run();
}

function baseInput() {
  return {
    serverId: '200',
    userId: 'u1',
    username: 'alice',
    cardName: 'Black Lotus',
    cardNameNormalized: 'black lotus',
    cardSet: null,
    cardImageUrl: null,
    finish: null,
    variant: null,
    collectorNumber: null,
    manapoolUrl: null,
    condition: 'nm',
    priceCents: 1000,
    quantity: 1,
    notes: null,
    game: 'mtg',
  } as const;
}

describe('createListing', () => {
  it('creates an active listing with a 30-day expiry', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    expect(listing.status).toBe('active');
    expect(listing.expiresAt - listing.createdAt).toBe(30 * 24 * 3600 * 1000);
    expect(listing.intent).toBe('have');
    expect(listing.accepts).toBe('cash');
  });

  it('blocks a second listing within the cooldown', () => {
    seedServer();
    createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    expect(() => createListing({ ...baseInput(), intent: 'want', accepts: 'cash' })).toThrow(
      /posting too quickly/,
    );
  });

  it('warns on a duplicate listing posted within 24h', () => {
    seedServer();
    const db = getDb();
    const past = Date.now() - 60_000; // past the 10s cooldown, inside the 24h window
    db.insert(listings)
      .values({
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
        cardName: 'Black Lotus',
        cardNameNormalized: 'black lotus',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        quantity: 1,
        notes: null,
        status: 'active',
        expiresAt: past + 30 * 24 * 3600 * 1000,
        createdAt: past,
        updatedAt: past,
      })
      .run();

    const result = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    expect(result.warning).toMatch(/already have an active matching listing/);
  });

  it('does not warn when the printing details differ', () => {
    seedServer();
    const db = getDb();
    const past = Date.now() - 60_000; // past the 10s cooldown, inside the 24h window
    db.insert(listings)
      .values({
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
        cardName: 'Black Lotus',
        cardNameNormalized: 'black lotus',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        quantity: 1,
        notes: null,
        status: 'active',
        expiresAt: past + 30 * 24 * 3600 * 1000,
        createdAt: past,
        updatedAt: past,
      })
      .run();

    const result = createListing({
      ...baseInput(),
      intent: 'have',
      accepts: 'cash',
      collectorNumber: '1',
      finish: 'foil',
    });
    expect(result.warning).toBeUndefined();
  });

  it('does not warn across differing kind for an otherwise identical row', () => {
    seedServer();
    const db = getDb();
    const past = Date.now() - 60_000; // past the 10s cooldown, inside the 24h window
    db.insert(listings)
      .values({
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
        cardName: 'Black Lotus',
        cardNameNormalized: 'black lotus',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        kind: 'sealed',
        sealedUuid: 'uuid-1',
        sealedCategory: 'booster_box',
        sealedSubtype: null,
        quantity: 1,
