describe('activeListingsForUser', () => {
  it("returns only the user's active listings, newest first", () => {
    seedServer();
    const { listing: first } = createListing({
      ...baseInput(),
      cardName: 'Card A',
      cardNameNormalized: 'card a',
      intent: 'have',
      accepts: 'cash',
    });
    const db = getDb();
    const later = first.createdAt + 20_000; // past the 10s cooldown
    db.insert(listings)
      .values({
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
        cardName: 'Card B',
        cardNameNormalized: 'card b',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
