/** Update owner-editable fields on a listing. */
export function updateListing(
  id: number,
  fields: {
    condition?: string | null;
    priceCents?: number | null;
    quantity?: number;
    notes?: string | null;
    cardSet?: string | null;
    cardName?: string;
    cardNameNormalized?: string;
    cardImageUrl?: string | null;
    collectorNumber?: string | null;
    manapoolUrl?: string | null;
    sealedUuid?: string | null;
    sealedCategory?: string | null;
    sealedSubtype?: string | null;
  },
): ListingRow | undefined {
  const db = getDb();
  const update: Partial<NewListingRow> = { updatedAt: now() };
  if (fields.condition !== undefined) update.condition = fields.condition;
  if (fields.priceCents !== undefined) update.priceCents = fields.priceCents;
  if (fields.quantity !== undefined) update.quantity = fields.quantity;
  if (fields.notes !== undefined) update.notes = fields.notes;
  if (fields.cardSet !== undefined) update.cardSet = fields.cardSet;
  if (fields.cardName !== undefined) update.cardName = fields.cardName;
  if (fields.cardNameNormalized !== undefined)
    update.cardNameNormalized = fields.cardNameNormalized;
  if (fields.cardImageUrl !== undefined) update.cardImageUrl = fields.cardImageUrl;
  if (fields.collectorNumber !== undefined) update.collectorNumber = fields.collectorNumber;
  if (fields.manapoolUrl !== undefined) update.manapoolUrl = fields.manapoolUrl;
  if (fields.sealedUuid !== undefined) update.sealedUuid = fields.sealedUuid;
  if (fields.sealedCategory !== undefined) update.sealedCategory = fields.sealedCategory;
  if (fields.sealedSubtype !== undefined) update.sealedSubtype = fields.sealedSubtype;
  db.update(listings).set(update).where(eq(listings.id, id)).run();
  return getListingById(id);
}

/** Mark a listing fulfilled. Only the owner may do this. */
export function fulfillListing(id: number): ListingRow | undefined {
  return setStatus(id, 'fulfilled');
}

/** Soft-delete a listing. Only the owner or an admin may do this. */
export function softDeleteListing(id: number): ListingRow | undefined {
  return setStatus(id, 'deleted');
}

type ListingStatus = 'active' | 'fulfilled' | 'deleted' | 'expired';

const ALLOWED_TRANSITIONS: Record<ListingStatus, Set<ListingStatus>> = {
  active: new Set(['fulfilled', 'deleted']),
  fulfilled: new Set(['deleted']),
  deleted: new Set(),
  expired: new Set(),
};

function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const listing = getListingById(id);
  if (!listing) {
    throw new Error(`listing #${id} not found`);
  }
  const current = listing.status as ListingStatus;
  if (!ALLOWED_TRANSITIONS[current]?.has(status)) {
    throw new Error(
      `cannot transition listing #${id} from '${current}' to '${status}'`,
    );
  }
  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

