it('can clear the sealed columns when a product falls out of the catalog', () => {
    seedServer();
    const { listing } = createListing({
      ...baseInput(),
      intent: 'have',
      accepts: 'cash',
      kind: 'sealed',
      sealedUuid: 'uuid-old',
      sealedCategory: 'bundle',
      sealedSubtype: 'default',
    });
    const updated = updateListing(listing.id, {
      sealedUuid: null,
      sealedCategory: null,
      sealedSubtype: null,
    });
    expect(updated?.sealedUuid).toBeNull();
    expect(updated?.sealedCategory).toBeNull();
    expect(updated?.sealedSubtype).toBeNull();
  });
});

describe('status transition guard', () => {
  it('allows active -> fulfilled', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const updated = fulfillListing(listing.id);
    expect(updated?.status).toBe('fulfilled');
  });

  it('allows active -> deleted', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const updated = softDeleteListing(listing.id);
    expect(updated?.status).toBe('deleted');
  });

  it('allows fulfilled -> deleted', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(listing.id);
    const updated = softDeleteListing(listing.id);
    expect(updated?.status).toBe('deleted');
  });

  it('forbids fulfilled -> fulfilled', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(listing.id);
    expect(() => fulfillListing(listing.id)).toThrow(
      "cannot transition listing #1 from 'fulfilled' to 'fulfilled'",
    );
  });

  it('forbids deleted -> fulfilled', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing.id);
    expect(() => fulfillListing(listing.id)).toThrow(
      "cannot transition listing #1 from 'deleted' to 'fulfilled'",
    );
  });

  it('forbids deleted -> deleted', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing.id);
    expect(() => softDeleteListing(listing.id)).toThrow(
      "cannot transition listing #1 from 'deleted' to 'deleted'",
    );
  });

  it('forbids active -> active (no-op)', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    expect(() => getListingById(listing.id)).not.toThrow();
  });
});

